class Solution { long long manhattan(int x1,int y1,int x2,int y2){return abs((long long)x1-x2)+abs((long long)y1-y2);}public:int minimumCost(vector<int>& start,vector<int>& target,vector<vector<int>>& specialRoads){int roads=specialRoads.size();vector<long long> distance(roads,LLONG_MAX);using State=array<long long,4>;priority_queue<State,vector<State>,greater<State>> queue;queue.push({0,start[0],start[1],-1});long long answer=manhattan(start[0],start[1],target[0],target[1]);while(!queue.empty()){auto [cost,xValue,yValue,indexValue]=queue.top();queue.pop();int x=xValue,y=yValue,index=indexValue;if(index>=0&&cost!=distance[index])continue;answer=min(answer,cost+manhattan(x,y,target[0],target[1]));for(int i=0;i<roads;++i){auto& road=specialRoads[i];long long next=cost+manhattan(x,y,road[0],road[1])+road[4];if(next<distance[i]){distance[i]=next;queue.push({next,road[2],road[3],i});}}}return answer;} };
